import sys,json,hashlib
from pathlib import Path
from prepare import E,S,run
expected={'fix-simple-fresh':'0b7359a3b2c5cda45df50c916fc86b817f447d2b464be76a665e02829eaf3a1f','fix-simple-upgrade':'3cc62585fa2218110cec689fa58f49ebfb3a83fc2f651dda871cc16258a2bade','fix-complex-fresh':'4fa71edad84f75e611e057937cc1f595d4be14ad9defa2025228787c9c580056','fix-complex-upgrade':'6c148ac1804c8848c05b0bfac3147d03252d09d3fc431baf16bd1d82cd91a499'}
for c in json.loads((E/'fix-targets.json').read_text(encoding='utf-8')):
 h=hashlib.sha256(Path(c['plan']).read_bytes()).hexdigest();assert h==expected[c['name']]
 body='## PLAN_REVIEW — affected WB-01 target inventory\n\nRole/model: independent target Reviewer / Codex GPT-6; exact preset unavailable; same session, no new source review. **PLAN_READY**, BLOCKER0, ADVISORY0 for this exact test inventory. Source2343df83a3a26ae83bc66d4009dd67a913eeea4e. Plan SHA256 `'+h+'`; exact plan/contract link published above.\n\nIndependently checked source/target/branch/PR/contract/current HEAD, before bytes+modes, all after hashes, conflicts0, default auto/Beads true, Windows observable mode0666. Fresh:78operations all before null and absent install-state; re-plan/negative controls/immediate rollback before helpers required. Upgrade:73operations, only scripts/install-overgate.py changes bytes, other before==after; existing gitignore preserved; project verifier/preserve owners excluded; Memory/Beads not managed; no helper replay or DB reinit. Existing local bd-init commit is on published branch ancestry.\n\n75sourcepaths across403→2343: installer changed, other74mode/blob identical; no whole-payload equivalence. Historical403 WB-01FAIL is not erased. Apply/no-op/controls/rollback/actual auto are NOT RUN by Reviewer and require execution evidence. This does not approve release/source readiness.\n\n— Independent target Reviewer (Codex GPT-6), published by Windows-QA (Codex GPT-6)\n'
 out=run([sys.executable,S/'.claude/tools/publish-pr-comment.py',c['pr'].rsplit('/',1)[1],'-'],c['target'],label=c['name']+'-review-publish',input=body).stdout.strip();assert out.startswith(c['pr']+'#')
 (E/(c['name']+'-approval.json')).write_text(json.dumps({'verdict':'PLAN_READY','plan_sha256':h,'evidence':out},indent=2),encoding='utf-8');print(c['name'],out,flush=True)
